---
import '../styles/global.css';
---

<!doctype html>
<html lang="en" data-theme="caramellatte">
	<head>
		<meta charset="utf-8" />
		<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
		<meta name="viewport" content="width=device-width, initial-scale=1.0" />
		<title>BUST — Sales Planning Workspace</title>
	</head>
	<body class="min-h-screen bg-base-100 text-base-content antialiased p-4 md:p-8 flex justify-center">
		<main class="w-full max-w-2xl space-y-6">
			<!-- Header -->
			<header class="border-b border-base-300 pb-4">
				<div class="flex items-center justify-between">
					<div>
						<h1 class="text-2xl font-bold tracking-tight">BUST</h1>
						<p class="text-sm text-base-content/70 mt-1">AI Sales Planning & Deal Execution Workspace</p>
					</div>
					<div class="badge badge-neutral text-xs">
						caramellatte
					</div>
				</div>
			</header>

			<!-- Proxy & Connection Card -->
			<section class="card bg-base-200 border border-base-300 shadow-xs">
				<div class="card-body p-5 space-y-4">
					<div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-base-300/60 pb-3">
						<div>
							<span class="text-xs font-semibold uppercase tracking-wider text-base-content/60">Backend Route</span>
							<p class="text-sm font-mono mt-0.5">Vite Proxy <span class="text-base-content/60">(/api, /health → 127.0.0.1:8000)</span></p>
						</div>
						<span id="backend-status-badge" class="badge badge-outline text-xs self-start sm:self-auto">
							Idle
						</span>
					</div>

					<!-- Action Controls -->
					<div class="flex flex-wrap gap-2">
						<button id="btn-health" type="button" class="btn btn-sm btn-outline">
							Check /health
						</button>
						<button id="btn-test-llm" type="button" class="btn btn-sm btn-neutral">
							Test LLM & NeatLogs
						</button>
					</div>

					<!-- Prompt Input (Optional customization) -->
					<div class="space-y-1">
						<label for="prompt-input" class="text-xs text-base-content/70">
							Test Prompt:
						</label>
						<input
							id="prompt-input"
							type="text"
							class="input input-sm input-bordered w-full bg-base-100 font-mono text-xs"
							value="Summarize our $150k enterprise deal value proposition in one sentence."
						/>
					</div>

					<!-- Response Output Box -->
					<div class="space-y-1">
						<div class="flex items-center justify-between text-xs text-base-content/70">
							<span>Output Log:</span>
							<span id="latency-label" class="font-mono"></span>
						</div>
						<pre id="output-box" class="p-3.5 rounded-lg bg-base-100 border border-base-300 font-mono text-xs overflow-x-auto whitespace-pre-wrap min-h-24 text-base-content">Click "Check /health" or "Test LLM & NeatLogs" to verify proxy communication.</pre>
					</div>
				</div>
			</section>

			<!-- Architecture Context Notice -->
			<footer class="text-center text-xs text-base-content/50 pt-2">
				Codespaces Proxy Enabled • Powered by LiteLLM (nova-pro) & NeatLogs Tracing
			</footer>
		</main>

		<script>
			const healthBtn = document.getElementById('btn-health');
			const testLlmBtn = document.getElementById('btn-test-llm');
			const promptInput = document.getElementById('prompt-input');
			const outputBox = document.getElementById('output-box');
			const statusBadge = document.getElementById('backend-status-badge');
			const latencyLabel = document.getElementById('latency-label');

			function setStatus(text, badgeClass) {
				if (statusBadge) {
					statusBadge.textContent = text;
					statusBadge.className = 'badge text-xs ' + badgeClass;
				}
			}

			// 1. Check Health via Proxy (/health)
			healthBtn?.addEventListener('click', async () => {
				const start = performance.now();
				setStatus('Checking...', 'badge-warning');
				if (outputBox) outputBox.textContent = 'Calling proxy: /health ...';
				if (latencyLabel) latencyLabel.textContent = '';

				try {
					const res = await fetch('/health');
					const data = await res.json();
					const duration = Math.round(performance.now() - start);

					if (res.ok) {
						setStatus(`HTTP ${res.status} OK`, 'badge-success');
						if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
						if (latencyLabel) latencyLabel.textContent = `${duration}ms`;
					} else {
						setStatus(`HTTP ${res.status}`, 'badge-error');
						if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
					}
				} catch (err) {
					setStatus('Failed', 'badge-error');
					if (outputBox) {
						outputBox.textContent = `Proxy connection error: ${err.message}\nMake sure FastAPI is running on port 8000.`;
					}
				}
			});

			// 2. Test LLM & NeatLogs via Proxy (/api/test-llm)
			testLlmBtn?.addEventListener('click', async () => {
				const start = performance.now();
				setStatus('Generating...', 'badge-warning');
				if (testLlmBtn) testLlmBtn.disabled = true;
				if (outputBox) outputBox.textContent = 'Calling proxy: POST /api/test-llm ...';
				if (latencyLabel) latencyLabel.textContent = '';

				const prompt = (promptInput?.value || '').trim() || 'Say hello in one short sentence.';

